"""Real confirmed-action HTTP/UI; activation stops at the owned busy-lock boundary."""
import asyncio
import base64
import copy
import hashlib
import importlib.metadata
import json
import os
import signal
import sys
import tempfile
from contextlib import contextmanager
from pathlib import Path

CLIENT_REVISION = '5c2139446586e74081cc38fd02f64ea49e9d7f33'
CLIENT_DIGEST = '4f28608db91419a4458d627b7c86e3163baa61c353255ccf4da04bde997d11a6'


def installed_identity():
    """Reuse paired-wheel checks; also bind the entire wheel payload and stamp."""
    from client_paired_server import verify_installed, verify_imports
    package = Path(os.environ['AMPLIFIER_TEST_INSTALLED_PACKAGE']).resolve(strict=True)
    record = json.loads(Path(os.environ['AMPLIFIER_TEST_ASSEMBLY_RECORD']).read_bytes())
    checkout = Path(os.environ['AMPLIFIER_TEST_SOURCE_ROOT']).resolve(strict=True)
    if (not Path(os.environ['AMPLIFIER_TEST_SOURCE_ROOT']).is_absolute()
            or checkout != Path(__file__).resolve().parents[2]
            or Path.cwd().resolve().is_relative_to(checkout) or package.is_relative_to(checkout)
            or not sys.flags.isolated or not sys.dont_write_bytecode
            or 'PYTHONHOME' in os.environ):
        raise ValueError('Installed pair requires -I -B and package/CWD outside the explicit checkout')
    fixture_digest = hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
    if fixture_digest != os.environ['AMPLIFIER_TEST_FIXTURE_SHA256']:
        raise ValueError('Fixture entry changed after the browser pinned it')
    if record['server']['revision'] != os.environ['AMPLIFIER_TEST_SERVER_REVISION']:
        raise ValueError('Assembly server is not the selected server revision')
    verify_installed(package, record)
    # Same external files:{wheel-relative-name:sha256} schema used by the
    # installed native fixture. Never accept RECORD alone as external provenance.
    identity_path = Path(os.environ['AMPLIFIER_TEST_INSTALLED_IDENTITY']).resolve(strict=True)
    files = json.loads(identity_path.read_bytes())['files']
    distribution = importlib.metadata.distribution('amplifier-unified')
    install_root = Path(distribution.locate_file('')).resolve()
    payload = {}
    for item in distribution.files or ():
        name = str(item)
        path = Path(name)
        metadata = len(path.parts) == 2 and path.parts[0].endswith('.dist-info')
        if (metadata and path.name in {'INSTALLER', 'REQUESTED', 'direct_url.json', 'RECORD', 'uv_cache.json'}
                or '__pycache__' in path.parts and path.suffix == '.pyc'):
            continue  # Precisely enumerated installer-created files, not payload.
        if '..' in path.parts:
            # Wheel entry points are generated by the installer outside site-packages.
            if path.name not in {'amplifier-unified', 'amplifier-unified-status'}:
                raise ValueError('Unexpected relocated installed entry: ' + name)
            continue
        if path.is_absolute():
            raise ValueError('Absolute wheel payload path')
        if not item.hash or item.hash.mode != 'sha256':
            raise ValueError('Unhashed installed payload: ' + name)
        target = Path(distribution.locate_file(item))
        if (any(parent.is_symlink() for parent in (target, *target.parents) if parent != install_root)
                or not target.resolve().is_relative_to(install_root)):
            raise ValueError('Nonlocal installed payload')
        body = target.read_bytes()
        digest = hashlib.sha256(body).digest()
        if base64.urlsafe_b64encode(digest).decode().rstrip('=') != item.hash.value:
            raise ValueError('Installed RECORD mismatch: ' + name)
        payload[name] = digest.hex()
    if not files or payload != files:
        raise ValueError('External identity must bind the complete installed wheel payload')
    app_roots = {Path(name).parts[0] for name in files
                 if Path(name).parts[0].startswith('amplifier_')
                 and not Path(name).parts[0].endswith('.dist-info')}
    for name in app_roots:
        directory = install_root / name
        for path in directory.rglob('*'):
            if path.is_file() and '__pycache__' not in path.parts:
                if (path.is_symlink() or not path.resolve().is_relative_to(install_root)
                        or path.relative_to(install_root).as_posix() not in files):
                    raise ValueError('Unmanifested application payload: ' + str(path))
    stamp_path = package / 'release-source.json'
    stamp_present = 'amplifier_web/release-source.json' in files
    if stamp_path.exists() != stamp_present:
        raise ValueError('Release-source stamp presence differs from the external wheel identity')
    stamp = json.loads(stamp_path.read_bytes()) if stamp_present else None
    if stamp_present:
        expected_stamp = {'schema': 1, 'repository': 'microsoft/amplifier-unified',
                          'revision': record['server']['revision'], 'version': record['server']['version']}
        if stamp != expected_stamp or type(stamp.get('schema')) is not int:
            raise ValueError('Installed release-source stamp differs from the selected server')
    source = record['client']['manifest']['source']
    if (source != {'repository': 'https://github.com/microsoft/amplifier-client-web',
                   'revision': CLIENT_REVISION}
            or os.environ['AMPLIFIER_TEST_CLIENT_REVISION'] != CLIENT_REVISION):
        raise ValueError('The probe requires accepted client 5c213, not another selection')
    selected = json.loads((checkout / 'components/web-client.source.json').read_bytes())
    if (selected['source'] != source or selected['inputsSha256'] != CLIENT_DIGEST
            or selected['delivery'] != {'type': 'directory', 'path': 'components/web-client'}):
        raise ValueError('Source selection does not bind this accepted client and digest')
    verify_imports(package)
    # Origin-check every loaded application package, not only amplifier_web.
    loaded = {}
    for name, module in tuple(sys.modules.items()):
        if name.split('.')[0] in app_roots:
            for directory in getattr(module, '__path__', ()):
                if not Path(directory).resolve().is_relative_to(install_root / name.split('.')[0]):
                    raise ValueError('Redirected application package search path: ' + name)
        location = getattr(module, '__file__', None)
        if name.split('.')[0] in app_roots and location:
            path = Path(location).resolve()
            if not path.is_relative_to(install_root):
                raise ValueError('Checkout-shadowed installed module: ' + name)
            relative = path.relative_to(install_root).as_posix()
            if relative not in files or hashlib.sha256(path.read_bytes()).hexdigest() != files[relative]:
                raise ValueError('Unmanifested installed module: ' + name)
            loaded[name] = {'path': str(path), 'sha256': files[relative]}
    return {'installedPackage': str(package), 'sourceStamp': stamp, 'sourceStampPresent': stamp_present,
            'selectedServerRevision': record['server']['revision'], 'clientSource': source,
            'fixtureSha256': fixture_digest,
            'clientInputsSha256': CLIENT_DIGEST, 'wheelPayloadFiles': len(payload),
            'wheelIdentitySha256': hashlib.sha256(identity_path.read_bytes()).hexdigest(),
            'loadedApplicationModules': len(loaded), 'applicationPackageRoots': sorted(app_roots),
            'changedBoundaryOrigins': {name: loaded[name] for name in (
                'amplifier_web.service', 'amplifier_web.management', 'amplifier_web.configuration_recovery',
                'amplifier_web.updates', 'amplifier_web.update_blockers', 'amplifier_web.update_health',
                'amplifier_web.app_updates') if name in loaded},
            'serverFiles': len(record['server']['files']), 'outsideCheckout': True,
            'isolated': True, 'bytecodeDisabled': True, 'nodeUnavailable': True}


async def serve():
    pair = os.environ.get('AMPLIFIER_TEST_UPDATE_RESTART_PAIR') == '1'
    if bool(os.environ.get('AMPLIFIER_TEST_INSTALLED_PACKAGE')) != pair:
        raise ValueError('Installed package mode requires the explicit update-restart pair opt-in')
    provenance = installed_identity() if pair else None
    from aiohttp import web
    import settings_ui_server as fixture
    import amplifier_web
    if pair:
        class ObservedRuntime(fixture.Runtime):
            """Synthetic absence/work observations; AppService/gate remain real."""
            def __init__(self):
                super().__init__()
                self.workers, self._preparations, self.calls = {}, {}, []

            def has_pending_operations(self):
                return False

            @contextmanager
            def stopped_boundary(self, session):
                assert session['id'] not in self.workers and not self._preparations
                yield

            async def start(self, *args, **kwargs):
                self.calls.append('start')
                raise AssertionError('This probe must never mount work')

            async def send(self, *args, **kwargs):
                self.calls.append('send')
                raise AssertionError('This probe must never send input')

        fixture.Runtime = ObservedRuntime
        create_app = fixture.create_app

        async def isolated_app(*args, **kwargs):
            kwargs.update(background_updates=False, background_work=False, preload_providers=False)
            return await create_app(*args, **kwargs)

        fixture.create_app = isolated_app
    with tempfile.TemporaryDirectory(prefix='unified-update-restart-') as tmp:
        app = await fixture.main(Path(tmp))
        service = app['service']
        manager = service.update_manager
        session = service._session()
        historical = []
        if pair:
            from amplifier_web.update_blockers import assess
            from amplifier_web.host.storage import SessionStore
            from amplifier_web.session_projection import hydrate, view_path
            from amplifier_web.state_records import load_owner
            historical.append(session)
            for index in range(1, 4):
                owner = service._new_session({'title': f'Stopped saved owner {index + 1}'})
                service.state['sessions'].append(owner)
                historical.append(owner)
            for index, owner in enumerate(historical):
                owner.update(status='stopped', interruptionRevision=1,
                    configurationBusy=True, configurationPending=True, configurationPendingRevision=23,
                    configurationRefresh={'phase': 'pending', 'revision': 23},
                    configurationOperationFence=f'fixture-retained-{index}',
                    pendingConfiguration={'operationId': f'fixture-retained-{index}', 'revision': 23,
                        'phase': 'error', 'stage': 'reading', 'effect': 'saved_not_mounted',
                        'recoveryRequired': True,
                        'error': 'Saved configuration does not match loaded-plan readback. Its operation remains unresolved.'})
                service._message(owner, 'user', f'Retained fixture request {index + 1}')
                service._message(owner, 'assistant', f'Retained fixture answer {index + 1}; never replay')
            service._save_changes(sessions={row['id'] for row in historical})
            originals = copy.deepcopy(historical)

            def committed_owners():
                values = {}
                for owner in historical:
                    sid = owner['id']
                    saved, control = load_owner(service.db, sid)
                    assert saved and saved['id'] == sid and saved.get('$viewPayload')
                    stored = {'sessions': [copy.deepcopy(saved)], 'runtimeControl': (
                        {sid: copy.deepcopy(control)} if control is not None else {})}
                    hydrate(service.data_dir, stored, service.db)
                    row = stored['sessions'][0]
                    assert row['id'] == sid and len(row['messages']) == 2
                    assert row['configurationPendingRevision'] == 23
                    assert row['pendingConfiguration'] == owner['pendingConfiguration']
                    values[sid] = {'reference': saved, 'runtime': control,
                                   'hydrated': json.loads(json.dumps(row))}
                assert len(values) == 4
                return values

            def saved_files():
                values = {}
                for owner in historical:
                    directory = SessionStore.for_app(service.data_dir, owner['workspace']).directory(
                        owner.get('runtimeSessionId') or owner['id'])
                    view = view_path(service.data_dir, owner)
                    assert view.is_file() and view.is_relative_to(directory)
                    files = {path.relative_to(directory).as_posix(): hashlib.sha256(path.read_bytes()).hexdigest()
                             for path in directory.rglob('*') if path.is_file()}
                    assert files and 'unified/view.json' in files
                    # Recovery files still use their owning management path; retain
                    # those too when present, not just the compatible view.
                    recovery = service.management.queued_path(owner['id']).parent
                    files.update({'configuration/' + path.relative_to(recovery).as_posix():
                                  hashlib.sha256(path.read_bytes()).hexdigest()
                                  for path in recovery.rglob('*') if path.is_file()})
                    values[owner['id']] = files
                assert len(values) == 4
                return values

            original_files = saved_files()
            original_committed = committed_owners()
            active = service._new_session({'title': 'Genuine active work'})
            service.state['sessions'].append(active)
            active.update(status='idle', configurationBusy=False)
            mode = 'historical'
        else:
            session.update(status='working', configurationBusy=True,
                           worktreeHandoffs=[{'id': 'retained-unknown', 'phase': 'unknown'}])
        await manager.publish(phase='app-staged', initialPreparation=False,
            pendingApp={'revision': 'a'*40, 'generation': 'b'*32, 'attemptId': 'qualified-one', 'latest': 'v99.0.0'},
            application={'status': 'update', 'canInstall': True, 'latest': 'v99.0.1'})
        # Exercise real action admission and asynchronous rejection without any
        # installation, runtime interruption, pointer promotion or host restart.
        await manager.lock.acquire()
        calls = []
        command = manager.command
        async def observed(action, args=None, command_id=None):
            if action == 'forceRestart':
                calls.append({'action': action, 'args': args, 'requestId': command_id})
            return await command(action, args, command_id)
        manager.command = observed
        def observation():
            value = {'calls': calls, 'unknown': any(item.get('phase') == 'unknown'
                         for owner in service.state['sessions'] for item in owner.get('worktreeHandoffs', [])),
                     'target': service.state['updates']['forceRestartTarget'],
                     'result': service.state['updates'].get('forceRestartResult'),
                     'blockers': service.state['updates']['blockers'],
                     'currentStatus': service.state['updates']['currentStatus']}
            if pair:
                current = {row['id']: row for row in service.state['sessions']}
                assert [current[row['id']] for row in historical] == originals
                assert historical == originals and saved_files() == original_files
                assert committed_owners() == original_committed
                assert service.runtime.calls == [] and not service.runtime.workers and not service.runtime._preparations
                gate = assess(service, application=True)
                value['pair'] = {'mode': mode, 'historicalIds': [row['id'] for row in historical],
                    'historicalStates': [{key: row[key] for key in ('status', 'configurationBusy',
                        'configurationPending', 'configurationPendingRevision', 'pendingConfiguration')}
                        for row in historical],
                    'historyAndConfigurationUnchanged': True, 'savedOwnerFilesUnchanged': True,
                    'committedOwnerReadbacksUnchanged': True,
                    'committedOwnerCount': len(original_committed),
                    'savedFilesPerOwner': {sid: len(files) for sid, files in original_files.items()},
                    'committedOwnerSha256': hashlib.sha256(json.dumps(
                        original_committed, sort_keys=True, separators=(',', ':')).encode()).hexdigest(),
                    'committedOwnerReadbacks': original_committed,
                    'appBusy': manager.app_busy(), 'componentBusy': manager.busy(),
                    'activationGate': gate['observation'], 'blockers': gate['blockers'],
                    'runtimeCalls': service.runtime.calls, 'activeId': active['id'],
                    'provenance': installed_identity()}
            return value

        async def control(request):
            nonlocal mode
            if request.headers.get('Authorization') != 'Bearer fixture-browser-control-token':
                raise web.HTTPForbidden()
            if request.method == 'POST':
                payload = await request.json() if request.can_read_body else {}
                if not isinstance(payload, dict) or set(payload) - {'mode'}:
                    raise web.HTTPBadRequest()
                if payload:
                    if not pair:
                        raise web.HTTPBadRequest()
                    next_mode = payload.get('mode')
                    if (mode, next_mode) not in {('historical', 'active'), ('active', 'unknown')}:
                        raise web.HTTPConflict(text='Probe transitions are ordered and non-replayable')
                    active.update(status='working', configurationBusy=True)
                    if next_mode == 'unknown':
                        active['worktreeHandoffs'] = [{'id': 'retained-unknown', 'phase': 'unknown'}]
                    mode = next_mode
                    await manager.publish()
                    return web.json_response(observation())
                async with service.lock:
                    service.state['updates']['pendingApp']['attemptId'] = 'qualified-two'
                await manager.publish()
            return web.json_response(observation())
        app.router.add_get('/fixture/update-restart', control)
        app.router.add_post('/fixture/update-restart', control)
        runner = web.AppRunner(app)
        await runner.setup()
        site = web.TCPSite(runner, '127.0.0.1', 0)
        await site.start()
        url = f'http://127.0.0.1:{site._server.sockets[0].getsockname()[1]}'
        app['allowed_origins'] |= {url}
        stopped = asyncio.Event()
        if os.name != 'nt':
            asyncio.get_running_loop().add_signal_handler(signal.SIGTERM, stopped.set)
        if pair:
            provenance = installed_identity()
        print(json.dumps({'url': url, 'package': amplifier_web.__file__,
                          'pair': provenance, 'pid': os.getpid()}), flush=True)
        try:
            await stopped.wait()
        finally:
            manager.lock.release()
            await runner.cleanup()
            if pair:
                installed_identity()


if __name__ == '__main__':
    # -I deliberately omits the script directory; expose only fixture siblings,
    # never the checkout root in installed mode.
    sys.path.insert(0, str(Path(__file__).resolve().parent))
    asyncio.run(serve())
